function openPresentationEvidenceFile(name) {
    const repo = _evidenceRepo();
    const viewer = document.getElementById("evidencePackViewer");
    const status = document.getElementById("evidencePackStatus");
    if (!repo || !viewer) return;
    fetch(`/presentation/evidence/file?repo_path=${encodeURIComponent(repo)}&name=${encodeURIComponent(name)}&as=html`)
        .then(r => r.json())
        .then(data => {
            if (!data.ok) {
                if (status) status.textContent = `Open failed: ${data.error || "unknown"}`;
                viewer.hidden = true;
                return;
            }
            viewer.hidden = false;
            // The server renders the Markdown to HTML (with the `tables`
            // extension), so pipe tables become real <table> elements that
            // the .evidence-viewer CSS can style.
            if (typeof data.html === "string" && data.html.length > 0) {
                viewer.innerHTML = `<div class="evidence-markdown">${data.html}</div>`;
            } else {
                // Fallback: server didn't render HTML; show raw text safely.
                viewer.innerHTML = `<pre class="evidence-raw">${_escapeHtml(data.content)}</pre>`;
            }
            if (status) status.textContent = `Showing ${data.name} (${data.size} bytes)`;
        })
        .catch(err => {
            if (status) status.textContent = `Failed: ${err}`;
        });
}
